#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const ll MOD = 1000000007LL;

    ll t;
    int l, r;
    cin >> t >> l >> r;

    vector<uint16_t> smallestPrime(r + 1, 0);

    for (int i = 2; 1LL * i * i <= r; ++i) {
        if (smallestPrime[i] != 0) continue;

        for (ll j = 1LL * i * i; j <= r; j += i) {
            if (smallestPrime[j] == 0)
                smallestPrime[j] = static_cast<uint16_t>(i);
        }
    }

    auto solve = [&](int x) -> ll {
        if (x == 1) return 0;

        int p = smallestPrime[x];
        if (p == 0)
            return 1LL * x * (x - 1) / 2;

        return 1LL * x * (p - 1) / 2 + 1LL * p * (p - 1) / 2;
    };

    t %= MOD;
    if (t < 0) t += MOD;

    ll answer = 0;
    ll power = 1;

    for (int i = l; i <= r; ++i) {
        answer = (answer + power * (solve(i) % MOD)) % MOD;
        power = power * t % MOD;
    }

    cout << answer << '\n';
    return 0;
}

