                value = 1LL * x * (x - 1) / 2;
            } else {
                value = 1LL * x * (p - 1) / 2
                      + p * (p - 1) / 2;
            }
        }

        answer = (answer + power * (value % MOD)) % MOD;
        power = power * t % MOD;
    }

    cout << answer << '\n';
    return 0;
